+// Slop guard: shortcuts that make work look done. It reads the run's own changes (a snapshot patch, or the
+// edit and write calls) and names each shortcut once; the loop reminds once, and the receipt carries the rest.
+
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type SlopRule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+export type SlopFinding = { rule: SlopRule; path: string; line?: string };
+
+const TEST_FILE = /\.(?:test|spec)\.[cm]?[jt]sx?$|_test\.go$|(?:^|\/)tests?\/|(?:^|\/)test_[^/]*\.py$|[^/]*_test\.py$/;
+const CODE_FILE = /\.(?:[cm]?[jt]sx?|py|go|rs|rb|java|kt|kts|swift|c|cc|cpp|h|hpp|cs|php|sh|bash|zsh|scala|lua|ex|exs|clj|dart|m|mm)$/;
+
+const SUPPRESSION = /@ts-(?:ignore|expect-error|nocheck)\b|\beslint-disable\b|\b(?:type|pyright|mypy):\s*ignore\b|\bnoqa\b|\bnolint\b|\bbiome-ignore\b|\bprettier-ignore\b|\bstylelint-disable\b/;
+const SWALLOWED = /\bcatch\s*(?:\([^)]*\))?\s*\{\s*\}|\.catch\s*\(\s*(?:\([^)]*\)|\w+)\s*=>\s*\{\s*\}\s*\)|^\s*except\b[^:]*:\s*pass\b/;
+const TYPE_ESCAPE = /\bas\s+any\b|:\s*any\b|<any>|\bas\s+unknown\s+as\b/;
+const STUB = /\bnot[ _-]?implemented\b|NotImplementedError|\bunimplemented!\s*\(|\btodo!\s*\(|\bTODO:\s*implement/i;
+const SKIPPED = /\b(?:test|it|describe|context)\.(?:skip|todo)\b|\b(?:xit|xtest|xdescribe)\s*\(|\.skip\s*\(|\bt\.Skip\s*\(|pytest\.mark\.skip|pytest\.skip\s*\(|#\[ignore\]/;
+const ASSERTION = /\bassert\w*\b|\bexpect\s*\(|\bshould\b|\brequire\s*\.|\bt\.(?:Error|Fatal|Fail)\b/;
+
+const isTestFile = (path: string) => TEST_FILE.test(path);
+
+// A test file whose assertions went away without any new one: deleting two asserts and adding `pass`.
+function weakened(c: FileChange): boolean {
+  const had = c.removed.filter((l) => ASSERTION.test(l)).length;
+  const has = c.added.filter((l) => ASSERTION.test(l)).length;
+  return had > 0 && has === 0;
+}
+
+function ruleFor(line: string, test: boolean): SlopRule | undefined {
+  if (SUPPRESSION.test(line)) return 'suppression';
+  if (SWALLOWED.test(line)) return 'swallowed-error';
+  if (TYPE_ESCAPE.test(line)) return 'type-escape';
+  if (STUB.test(line)) return 'stub';
+  if (test && SKIPPED.test(line)) return 'test-skipped';
+  return undefined;
+}
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  for (const c of changes) {
+    const test = isTestFile(c.path);
+    if (c.deleted) {
+      if (test) out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (test && weakened(c)) out.push({ rule: 'test-weakened', path: c.path });
+    if (!CODE_FILE.test(c.path)) continue;
+    for (const line of c.added) {
+      const rule = ruleFor(line, test);
+      if (rule) out.push({ rule, path: c.path, line: line.trim() });
+    }
+  }
+  return out;
+}
+
+export const findingLabel = (f: SlopFinding) => `${f.rule} ${f.path}${f.line ? `: ${f.line}` : ''}`;
+
+// A -U0 git patch, as the shadow snapshot writes it: one FileChange per file, deleted files included.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const raw of patch.split('\n')) {
+    if (raw.startsWith('diff --git ')) {
+      cur = { path: '', added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+      continue;
+    }
+    if (!cur) continue;
+    if (raw.startsWith('deleted file mode ')) {
+      cur.deleted = true;
+      continue;
+    }
+    if (raw.startsWith('--- ')) {
+      const p = raw.slice(4).replace(/\t.*$/, '');
+      if (p !== '/dev/null' && !cur.path) cur.path = p.replace(/^a\//, '');
+      continue;
+    }
+    if (raw.startsWith('+++ ')) {
+      const p = raw.slice(4).replace(/\t.*$/, '');
+      if (p === '/dev/null') cur.deleted = true;
+      else cur.path = p.replace(/^b\//, '');
+      continue;
+    }
+    if (raw.startsWith('@@')) {
+      inHunk = true;
+      continue;
+    }
+    if (!inHunk) continue;
+    if (raw.startsWith('+')) cur.added.push(raw.slice(1));
+    else if (raw.startsWith('-')) cur.removed.push(raw.slice(1));
+  }
+  return out;
+}
