+import type { EventOf, SessionEvent } from '../types.ts';
+import type { TextEdit } from '../tools/edit.ts';
+
+// A run's own changes, in the shape both a git patch and the edit/write calls give.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+
+export type SlopRule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+export type SlopFinding = { rule: SlopRule; path: string; line?: string };
+
+// Code files only: prose about `catch {}` or `as any` is not a shortcut in the code.
+const CODE = /\.(?:[cm]?[jt]sx?|py|go|rs|rb|java|kt|kts|cs|c|h|cc|cpp|hpp|swift|scala|php|sh|bash|zsh|lua|ex|exs|dart|vue|svelte)$/i;
+
+const isTestPath = (path: string) =>
+  /(^|\/)(tests?|__tests__)\//.test(path) || /\.(test|spec)\.[cm]?[jt]sx?$/i.test(path) || /_(test|spec)\.\w+$/i.test(path) || /(^|\/)test_[^/]*\.py$/.test(path);
+
+const ASSERT = /\bassert\w*\b|\bexpect\s*\(|\.should\b|\bt\.(?:Error|Fatal|Fatalf)\b|\bassert_eq!|\bassert!|require\./;
+const SKIP = /\b(?:test|it|describe)\.skip\b|\bx(?:it|describe)\s*\(|\bt\.Skip\b|@Ignore\b|@pytest\.mark\.skip\b|#\[ignore\]/;
+
+// One finding per added line at most, first rule wins.
+const LINE_RULES: [SlopRule, RegExp][] = [
+  ['suppression', /@ts-ignore\b|@ts-nocheck\b|@ts-expect-error\b|eslint-disable\b|#\s*type:\s*ignore\b|#\s*noqa\b|pyright:\s*ignore\b|nolint\b|pylint:\s*disable\b/],
+  ['swallowed-error', /catch\s*(?:\([^)]*\))?\s*\{\s*\}|except\b[^:]*:\s*pass\s*$|\bif\s+err\s*!=\s*nil\s*\{\s*\}/],
+  ['type-escape', /\bas\s+any\b/],
+  ['stub', /not[\s-]?implemented|unimplemented!|\btodo!\(\)/i],
+];
+
+// Shortcuts that make work look done: tests removed or hollowed out, checks silenced, errors swallowed,
+// types escaped and stubs left in place.
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  const seen = new Set<string>();
+  const add = (rule: SlopRule, path: string, line?: string) => {
+    const key = `${rule} ${path}${line === undefined ? '' : `: ${line}`}`;
+    if (seen.has(key)) return;
+    seen.add(key);
+    out.push(line === undefined ? { rule, path } : { rule, path, line });
+  };
+  for (const c of changes) {
+    const test = isTestPath(c.path);
+    if (test && c.deleted) {
+      add('test-deleted', c.path);
+      continue;
+    }
+    if (!CODE.test(c.path)) continue;
+    for (const raw of c.added) {
+      const line = raw.trim();
+      if (!line) continue;
+      if (test && SKIP.test(line)) add('test-skipped', c.path, line);
+      const rule = LINE_RULES.find(([, re]) => re.test(line))?.[0];
+      if (rule) add(rule, c.path, line);
+    }
+    if (test) {
+      const asserts = (ls: string[]) => ls.filter((l) => ASSERT.test(l)).length;
+      if (asserts(c.removed) > asserts(c.added)) add('test-weakened', c.path);
+    }
+  }
