+}
+
+const slopFlag = (f: SlopFinding) => `${f.rule} ${f.path}${f.line === undefined ? '' : `: ${f.line}`}`;
+export const slopFlags = (findings: SlopFinding[]) => [...new Set(findings.map(slopFlag))];
+
+const strip = (path: string) => path.replace(/^[ab]\//, '');
+
+// Reads the `-U0` patch the shadow snapshots produce, so a bash deletion counts like a write.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let oldPath = '';
+  for (const line of patch.split('\n')) {
+    if (line.startsWith('diff --git ')) {
+      cur = undefined;
+      oldPath = '';
+    } else if (line.startsWith('--- ')) {
+      oldPath = strip(line.slice(4).trim());
+    } else if (line.startsWith('+++ ')) {
+      const next = strip(line.slice(4).trim());
+      const deleted = next === '/dev/null';
+      cur = { path: deleted ? oldPath : next, added: [], removed: [], deleted };
+      out.push(cur);
+    } else if (cur && !line.startsWith('@@') && !line.startsWith('\\')) {
+      if (line.startsWith('+')) cur.added.push(line.slice(1));
+      else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+    }
+  }
