+
+const lines = (s: string) => s.split('\n').filter((l) => l.length > 0);
+
+// Without snapshots, the run's changes are the completed edit and write calls it made.
+export function changesFromEvents(events: SessionEvent[]): FileChange[] {
+  const intents = new Map<string, EventOf<'tool_intent'>>();
+  const byPath = new Map<string, FileChange>();
+  for (const e of events) {
+    if (e.kind === 'request') intents.clear();
+    if (e.kind === 'tool_intent') intents.set(e.callId, e);
+    if (e.kind !== 'tool_result' || e.status !== 'completed') continue;
+    const intent = intents.get(e.callId);
+    if (!intent || (intent.tool !== 'edit' && intent.tool !== 'write')) continue;
+    const path = String(intent.input.path ?? '');
+    if (!path) continue;
+    const c = byPath.get(path) ?? { path, added: [], removed: [], deleted: false };
+    if (intent.tool === 'write') c.added.push(...lines(String(intent.input.content ?? '')));
+    else
+      for (const edit of Array.isArray(intent.input.edits) ? (intent.input.edits as TextEdit[]) : []) {
+        c.added.push(...lines(String(edit.new_text ?? '')));
+        c.removed.push(...lines(String(edit.old_text ?? '')));
+      }
+    byPath.set(path, c);
+  }
+  return [...byPath.values()];
+}
