+  });
+
+  test('50 units get the 10% tier only', () => {
+    // 50 pens = 6000; 10% off = 600; 5400 >= 5000 ships free; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('lines of the same sku are merged before pricing', () => {
+    // 6 + 4 mugs = 10 units = 4500; 5% off = 225; tax 7% of 4275 + 800 = 355
+    const t = totals(cart('US', [['MUG', 6], ['MUG', 4]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t.lines[0]).toMatchObject({ sku: 'MUG', quantity: 10, subtotal: 4500, discount: 225, total: 4275 });
+    expect(t).toMatchObject({ subtotal: 4275, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('the coupon lowers the amount used for free shipping', () => {
+    // 2 bags = 4400, free in the UK; SAVE10 -440 = 3960 < 4000, so shipping 700
+    // tax 20% of 3960 + 700 = 932
+    expect(totals(cart('UK', [['BAG', 2]], 'SAVE10'))).toMatchObject({ subtotal: 4400, coupon: 440, shipping: 700, tax: 932, total: 5592 });
+  });
+
+  test('UK free shipping starts at 4000', () => {
+    // 9 mugs = 4050 >= 4000; tax 20% of 4050 = 810
+    expect(totals(cart('UK', [['MUG', 9]]))).toMatchObject({ subtotal: 4050, shipping: 0, tax: 810, total: 4860 });
+  });
+
+  test('FLAT5 never takes an order below zero', () => {
+    // 3 pens = 360: FLAT5 capped at 360; shipping 800; tax 7% of 800 = 56
+    expect(totals(cart('US', [['PEN', 3]], 'FLAT5'))).toMatchObject({ subtotal: 360, coupon: 360, shipping: 800, tax: 56, total: 856 });
+  });
+});

