diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/pricing-rules.test.ts b/test/pricing-rules.test.ts
--- a/test/pricing-rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/pricing-rules.test.ts	2026-11-06 19:15:29.590079820 +0000
@@ -0,0 +1,35 @@
+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('the bulk discount starts at 10 units, not 11', () => {
+    // 10 pens = 1200; 5% bulk = 60 -> 1140; shipping 800; tax 7% of 1940 = 135.8 -> 136
+    expect(totals(cart('US', [['PEN', 10]]))).toMatchObject({ subtotal: 1140, shipping: 800, tax: 136, total: 2076 });
+  });
+
+  test('50 units get 10% off, not 5%', () => {
+    // 50 pens = 6000; 10% bulk = 600 -> 5400 >= 5000 so free shipping; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('lines of the same sku are merged before the bulk tier is chosen', () => {
+    // 5 + 5 mugs merge to 10 units: 4500 - 5% (225) = 4275; shipping 800; tax 7% of 5075 = 355.25 -> 355
+    const t = totals(cart('US', [['MUG', 5], ['MUG', 5]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t.lines[0]).toMatchObject({ sku: 'MUG', quantity: 10, subtotal: 4500, discount: 225, total: 4275 });
+    expect(t).toMatchObject({ subtotal: 4275, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('free shipping is decided on the discounted subtotal', () => {
+    // 12 mugs = 5400; 5% bulk = 270 -> 5130; FLAT5 -> 4630 < 5000, so shipping is charged
+    // tax 7% of (4630 + 800) = 380.1 -> 380
+    expect(totals(cart('US', [['MUG', 12]], 'FLAT5'))).toMatchObject({ subtotal: 5130, coupon: 500, shipping: 800, tax: 380, total: 5810 });
+  });
+
+  test('UK free shipping starts at 4000', () => {
+    // 2 bags = 4400 >= 4000; tax 20% of 4400 = 880
+    expect(totals(cart('UK', [['BAG', 2]]))).toMatchObject({ subtotal: 4400, shipping: 0, tax: 880, total: 5280 });
+  });
+});

