@@ -7,10 +7,61 @@
 //
 // formatDuration: milliseconds to the shortest text using d, h, m, s and ms, largest unit first, zero parts
 // left out, no spaces: 5_400_000 -> "1h30m", 1_500 -> "1s500ms", 0 -> "0s". Throws on a negative number.
+const UNIT_MS: Record<string, number> = {
+  d: 86_400_000,
+  h: 3_600_000,
+  m: 60_000,
+  s: 1_000,
+  ms: 1,
+};
+
+const UNITS: [unit: string, ms: number][] = [
+  ['d', UNIT_MS.d],
+  ['h', UNIT_MS.h],
+  ['m', UNIT_MS.m],
+  ['s', UNIT_MS.s],
+  ['ms', UNIT_MS.ms],
+];
+
 export function parseDuration(text: string): number {
-  throw new Error('not implemented');
+  const fail = (): never => {
+    throw new Error(`Invalid duration: "${text}"`);
+  };
+
+  const trimmed = text.trim();
+  if (trimmed === '') fail();
+
+  const part = /(\d+(?:\.\d+)?)(ms|d|h|m|s)/g;
+  let total = 0;
+  let end = 0;
+  let first = true;
+  for (let match = part.exec(trimmed); match !== null; match = part.exec(trimmed)) {
+    const gap = trimmed.slice(end, match.index);
+    if (!/^\s*$/.test(gap) || (first && match.index !== 0)) fail();
+    first = false;
+    total += Number(match[1]) * UNIT_MS[match[2]];
+    end = part.lastIndex;
+  }
+
+  if (first || end !== trimmed.length) fail();
+  return Math.round(total);
 }

 export function formatDuration(ms: number): string {
-  throw new Error('not implemented');
+  if (!Number.isFinite(ms) || ms < 0) {
+    throw new Error(`Invalid duration: ${ms}`);
+  }
+
+  let rest = Math.round(ms);
+  if (rest === 0) return '0s';
+
+  let out = '';
+  for (const [unit, size] of UNITS) {
+    const count = Math.floor(rest / size);
+    if (count > 0) {
+      out += `${count}${unit}`;
+      rest -= count * size;
+    }
+  }
+  return out;
 }
