   }

   get(key: K): V | undefined {
-    throw new Error('not implemented');
+    const entry = this.entries.get(key);
+    if (entry === undefined) return undefined;
+
+    if (this.now() >= entry.expiresAt) {
+      this.entries.delete(key);
+      this.onEvict?.(key, entry.value, 'expired');
+      return undefined;
+    }
+
+    this.entries.delete(key);
+    this.entries.set(key, entry);
+    return entry.value;
   }

   set(key: K, value: V): void {
-    throw new Error('not implemented');
+    const now = this.now();
+    this.entries.delete(key);
+    this.entries.set(key, { value, expiresAt: now + this.ttlMs });
+
+    while (this.entries.size > this.capacity) {
+      const expired = this.firstExpired(now);
+      if (expired !== undefined) {
+        const entry = this.entries.get(expired)!;
+        this.entries.delete(expired);
+        this.onEvict?.(expired, entry.value, 'expired');
+        continue;
+      }
+
+      const oldest = this.entries.entries().next().value!;
+      this.entries.delete(oldest[0]);
+      this.onEvict?.(oldest[0], oldest[1].value, 'capacity');
+    }
   }

   delete(key: K): boolean {
-    throw new Error('not implemented');
+    const entry = this.entries.get(key);
+    if (entry === undefined) return false;
+
+    this.entries.delete(key);
+    if (this.now() >= entry.expiresAt) {
+      this.onEvict?.(key, entry.value, 'expired');
+      return false;
+    }
+
+    this.onEvict?.(key, entry.value, 'delete');
+    return true;
   }

   get size(): number {
-    throw new Error('not implemented');
+    const now = this.now();
+    let live = 0;
+    for (const entry of this.entries.values()) {
+      if (now < entry.expiresAt) live++;
+    }
+    return live;
   }

   keys(): K[] {
-    throw new Error('not implemented');
+    const now = this.now();
+    const keys: K[] = [];
+    for (const [key, entry] of this.entries) {
+      if (now < entry.expiresAt) keys.push(key);
+    }
+    return keys.reverse();
+  }
+
+  private firstExpired(now: number): K | undefined {
+    for (const [key, entry] of this.entries) {
