diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/rules.test.ts b/test/rules.test.ts
--- a/test/rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/rules.test.ts	2026-11-06 19:17:12.134085916 +0000
@@ -0,0 +1,194 @@
+import { expect, test } from 'bun:test';
+import { formatDuration, parseDuration } from '../src/duration.ts';
+import { slugify, uniqueSlug } from '../src/slug.ts';
+import { LRU } from '../src/lru.ts';
+
+test('parseDuration accepts every unit, fractions and spaces', () => {
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('2d 4h')).toBe(2 * 86_400_000 + 4 * 3_600_000);
+  expect(parseDuration('1d1h1m1s1ms')).toBe(86_400_000 + 3_600_000 + 60_000 + 1_000 + 1);
+  expect(parseDuration(' 90s ')).toBe(90_000);
+  expect(parseDuration('1h  30m')).toBe(5_400_000);
+  expect(parseDuration('0.5s')).toBe(500);
+  expect(parseDuration('1.5ms')).toBe(2);
+});
+
+test('parseDuration rejects anything that is not number-unit parts', () => {
+  for (const input of ['', '   ', '10', '5x', 'h', '-1s', '1h 30', '1 h', '1hx', '1H', 's', '1.', '.5h']) {
+    expect(() => parseDuration(input)).toThrow(input);
+  }
+});
+
+test('formatDuration uses the largest units and leaves zero parts out', () => {
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(999)).toBe('999ms');
+  expect(formatDuration(1_000)).toBe('1s');
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(90_000)).toBe('1m30s');
+  expect(formatDuration(86_400_000)).toBe('1d');
+  expect(formatDuration(86_400_000 + 3_600_000 + 60_000 + 1_000 + 1)).toBe('1d1h1m1s1ms');
+});
+
+test('formatDuration throws on negative numbers', () => {
+  expect(() => formatDuration(-1)).toThrow();
+  expect(() => formatDuration(-0.5)).toThrow();
+});
+
+test('slugify removes diacritics and maps special letters', () => {
+  expect(slugify('à ç ñ ź')).toBe('a-c-n-z');
+  expect(slugify('Straße')).toBe('strasse');
+  expect(slugify('Æon Œuvre Øresund Łódź Đorđe')).toBe('aeon-oeuvre-oresund-lodz-dorde');
+  expect(slugify('İstanbul')).toBe('istanbul');
+});
+
+test('slugify collapses separators and trims them', () => {
+  expect(slugify('  --Foo__Bar!!  ')).toBe('foo-bar');
+  expect(slugify('Café  déjà\tvu')).toBe('cafe-deja-vu');
+  expect(slugify('42 Things')).toBe('42-things');
+  expect(slugify('!!!')).toBe('');
+});
+
+test('slugify cuts at max without a dangling separator', () => {
+  expect(slugify('ab-cd-ef', 5)).toBe('ab-cd');
+  expect(slugify('ab-cd-ef', 6)).toBe('ab-cd');
+  expect(slugify('ab-cd-ef', 2)).toBe('ab');
+  expect(slugify('ab-cd-ef', 1)).toBe('a');
+  expect(slugify('ab-cd-ef', 0)).toBe('');
+  expect(slugify('abcdef', 3)).toBe('abc');
+  expect(slugify('abc-def', 3)).toBe('abc');
+  expect(slugify('ab-cd-ef', 8)).toBe('ab-cd-ef');
+  expect(slugify('ab-cd-ef', 20)).toBe('ab-cd-ef');
+});
+
+test('uniqueSlug finds the first free suffix without mutating taken', () => {
+  const taken = new Set(['post', 'post-2', 'post-4']);
+  expect(uniqueSlug('post', taken)).toBe('post-3');
+  expect(uniqueSlug('other', taken)).toBe('other');
+  expect(uniqueSlug('post', new Set(['post', 'post-3']))).toBe('post-2');
+  expect([...taken]).toEqual(['post', 'post-2', 'post-4']);
+});
+
+test('lru evicts the least recently used entry with reason capacity', () => {
+  const evicted: [string, number, string][] = [];
+  const cache = new LRU<string, number>(2, 1000, () => 0);
+  cache.onEvict = (key, value, reason) => evicted.push([key, value, reason]);
+
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1);
+  cache.set('c', 3);
+
+  expect(evicted).toEqual([['b', 2, 'capacity']]);
+  expect(cache.keys()).toEqual(['c', 'a']);
+  expect(cache.size).toBe(2);
+});
+
+test('lru overwriting a key makes it the most recently used', () => {
+  const cache = new LRU<string, number>(2, 1000, () => 0);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.set('a', 3);
+  cache.set('c', 4);
+
+  expect(cache.keys()).toEqual(['c', 'a']);
+  expect(cache.get('a')).toBe(3);
+  expect(cache.get('b')).toBeUndefined();
+});
+
+test('lru entries are live until exactly their expiry time', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 1000, () => t);
+  cache.set('a', 1);
+  t = 999;
+  expect(cache.get('a')).toBe(1);
+  t = 1000;
+  expect(cache.size).toBe(0);
+  expect(cache.keys()).toEqual([]);
+  expect(cache.get('a')).toBeUndefined();
+});
+
+test('lru get on an expired entry evicts it as expired', () => {
+  const evicted: [string, number, string][] = [];
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (key, value, reason) => evicted.push([key, value, reason]);
+  cache.set('a', 1);
+  t = 100;
+
+  expect(cache.get('a')).toBeUndefined();
+  expect(evicted).toEqual([['a', 1, 'expired']]);
+  expect(cache.size).toBe(0);
+});
+
+test('lru delete distinguishes live, expired and missing entries', () => {
+  const evicted: [string, number, string][] = [];
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (key, value, reason) => evicted.push([key, value, reason]);
+
+  cache.set('live', 1);
+  expect(cache.delete('live')).toBe(true);
+  expect(evicted).toEqual([['live', 1, 'delete']]);
+
+  cache.set('old', 2);
+  t = 100;
+  expect(cache.delete('old')).toBe(false);
+  expect(evicted).toEqual([
+    ['live', 1, 'delete'],
+    ['old', 2, 'expired'],
+  ]);
+
+  expect(cache.delete('missing')).toBe(false);
+  expect(evicted).toHaveLength(2);
+});
+
+test('lru size and keys count only live entries, most recent first', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(3, 100, () => t);
+  cache.set('a', 1);
+  t = 50;
+  cache.set('b', 2);
+  t = 60;
+  cache.set('c', 3);
+  t = 120;
+
+  expect(cache.size).toBe(2);
+  expect(cache.keys()).toEqual(['c', 'b']);
+  expect(cache.get('a')).toBeUndefined();
+  expect(cache.get('b')).toBe(2);
+});
+
+test('lru expired entries count toward capacity and are evicted first', () => {
+  const evicted: [string, number, string][] = [];
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (key, value, reason) => evicted.push([key, value, reason]);
+
+  cache.set('a', 1);
+  t = 50;
+  cache.set('b', 2);
+  t = 100; // a is expired, b is still live
+  cache.set('c', 3);
+
+  expect(evicted).toEqual([['a', 1, 'expired']]);
+  expect(cache.keys()).toEqual(['c', 'b']);
+
+  t = 150; // b is now expired too, c is still live
+  cache.set('d', 4);
+  expect(evicted).toEqual([
+    ['a', 1, 'expired'],
+    ['b', 2, 'expired'],
+  ]);
+  expect(cache.keys()).toEqual(['d', 'c']);
+});
+
+test('lru with capacity zero stores nothing', () => {
+  const evicted: [string, number, string][] = [];
+  const cache = new LRU<string, number>(0, 1000, () => 0);
+  cache.onEvict = (key, value, reason) => evicted.push([key, value, reason]);
+  cache.set('a', 1);
+  expect(evicted).toEqual([['a', 1, 'capacity']]);
+  expect(cache.size).toBe(0);
+  expect(cache.keys()).toEqual([]);
+});

