 // formatDuration: milliseconds to the shortest text using d, h, m, s and ms, largest unit first, zero parts
 // left out, no spaces: 5_400_000 -> "1h30m", 1_500 -> "1s500ms", 0 -> "0s". Throws on a negative number.
+const UNIT_MS: Record<string, number> = {
+  d: 86_400_000,
+  h: 3_600_000,
+  m: 60_000,
+  s: 1_000,
+  ms: 1,
+};
+
+const PART = /(\d+(?:\.\d+)?)(ms|d|h|m|s)/g;
+const DURATION = /^\d+(?:\.\d+)?(?:ms|d|h|m|s)(?:\s*\d+(?:\.\d+)?(?:ms|d|h|m|s))*$/;
+
+const FORMAT_UNITS: [string, number][] = [
+  ['d', 86_400_000],
+  ['h', 3_600_000],
+  ['m', 60_000],
+  ['s', 1_000],
+  ['ms', 1],
+];
+
 export function parseDuration(text: string): number {
-  throw new Error('not implemented');
+  const trimmed = text.trim();
+  if (!DURATION.test(trimmed)) {
+    throw new Error(`invalid duration "${text}"`);
+  }
+
+  let total = 0;
+  for (const match of trimmed.matchAll(PART)) {
+    total += Number(match[1]) * UNIT_MS[match[2]];
+  }
+  return Math.round(total);
 }

 export function formatDuration(ms: number): string {
-  throw new Error('not implemented');
+  if (ms < 0) {
+    throw new Error(`cannot format negative duration ${ms}`);
+  }
+
+  let rest = Math.floor(ms);
+  let text = '';
+  for (const [unit, size] of FORMAT_UNITS) {
+    const amount = Math.floor(rest / size);
+    if (amount > 0) {
+      text += `${amount}${unit}`;
+      rest -= amount * size;
+    }
+  }
+  return text || '0s';
 }
