diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/rules.test.ts b/test/rules.test.ts
--- a/test/rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/rules.test.ts	2026-11-06 19:17:51.010088226 +0000
@@ -0,0 +1,161 @@
+import { expect, test } from 'bun:test';
+import { formatDuration, parseDuration } from '../src/duration.ts';
+import { slugify, uniqueSlug } from '../src/slug.ts';
+import { LRU } from '../src/lru.ts';
+
+test('parseDuration units, fractions and spaces', () => {
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('2d 4h')).toBe(2 * 86_400_000 + 4 * 3_600_000);
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('1h 30m')).toBe(5_400_000);
+  expect(parseDuration('  1d2h3m4s5ms  ')).toBe(
+    86_400_000 + 2 * 3_600_000 + 3 * 60_000 + 4_000 + 5,
+  );
+});
+
+test('parseDuration rounds to whole milliseconds', () => {
+  expect(parseDuration('0.0006s')).toBe(1);
+  expect(parseDuration('0.0004s')).toBe(0);
+});
+
+test('parseDuration rejects invalid text with the input in the message', () => {
+  for (const bad of ['', '10', '5x', 'h', '-1s', '1h 30', '1 h', '1h,30m', '1H']) {
+    expect(() => parseDuration(bad)).toThrow(`"${bad}"`);
+  }
+});
+
+test('formatDuration', () => {
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(1)).toBe('1ms');
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(90_061_001)).toBe('1d1h1m1s1ms');
+  expect(formatDuration(2 * 86_400_000)).toBe('2d');
+  expect(() => formatDuration(-1)).toThrow();
+});
+
+test('slugify strips diacritics and special letters', () => {
+  expect(slugify('ÀÇ Ñ Ź')).toBe('ac-n-z');
+  expect(slugify('Straße Æon Œuvre Øresund Łódź Đakovo')).toBe(
+    'strasse-aeon-oeuvre-oresund-lodz-dakovo',
+  );
+});
+
+test('slugify collapses separators and trims them', () => {
+  expect(slugify('  --Hello,,, World--  ')).toBe('hello-world');
+  expect(slugify('A1 b2')).toBe('a1-b2');
+  expect(slugify('')).toBe('');
+  expect(slugify('!!!')).toBe('');
+});
+
+test('slugify max cuts at the last dash within max', () => {
+  expect(slugify('ab-cd-ef', 5)).toBe('ab-cd');
+  expect(slugify('abc-def', 3)).toBe('abc');
+  expect(slugify('abcdef-gh', 5)).toBe('abcde');
+  expect(slugify('hello world', 20)).toBe('hello-world');
+  expect(slugify('hello world', 8)).toBe('hello');
+});
+
+test('uniqueSlug skips taken names', () => {
+  const taken = new Set(['post', 'post-2']);
+  expect(uniqueSlug('post', taken)).toBe('post-3');
+  expect(uniqueSlug('page', taken)).toBe('page');
+});
+
+test('lru removes an expired entry on get', () => {
+  let t = 0;
+  const evicted: Array<[string, number, string]> = [];
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (key, value, reason) => evicted.push([key, value, reason]);
+
+  cache.set('a', 1);
+  t = 50;
+  cache.set('b', 2);
+  t = 100;
+
+  expect(cache.get('a')).toBeUndefined();
+  expect(evicted).toEqual([['a', 1, 'expired']]);
+  expect(cache.keys()).toEqual(['b']);
+  expect(cache.size).toBe(1);
+});
+
+test('lru evicts expired entries before live ones on overflow', () => {
+  let t = 0;
+  const evicted: Array<[string, string]> = [];
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (key, _value, reason) => evicted.push([key, reason]);
+
+  cache.set('a', 1);
+  t = 10;
+  cache.set('b', 2);
+  t = 150;
+  cache.set('c', 3);
+
+  expect(evicted).toEqual([
+    ['a', 'expired'],
+    ['b', 'expired'],
+  ]);
+  expect(cache.keys()).toEqual(['c']);
+  expect(cache.size).toBe(1);
+});
+
+test('lru evicts the least recently used live entry on overflow', () => {
+  let t = 0;
+  const evicted: Array<[string, string]> = [];
+  const cache = new LRU<string, number>(2, 1000, () => t);
+  cache.onEvict = (key, _value, reason) => evicted.push([key, reason]);
+
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1);
+  cache.set('c', 3);
+
+  expect(evicted).toEqual([['b', 'capacity']]);
+  expect(cache.keys()).toEqual(['c', 'a']);
+});
+
+test('lru get does not extend the ttl', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+
+  cache.set('a', 1);
+  t = 50;
+  expect(cache.get('a')).toBe(1);
+  t = 100;
+  expect(cache.get('a')).toBeUndefined();
+});
+
+test('lru delete reports live, expired and missing entries', () => {
+  let t = 0;
+  const evicted: Array<[string, string]> = [];
+  const cache = new LRU<string, number>(3, 100, () => t);
+  cache.onEvict = (key, _value, reason) => evicted.push([key, reason]);
+
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.delete('a')).toBe(true);
+  t = 100;
+  expect(cache.delete('b')).toBe(false);
+  expect(cache.delete('missing')).toBe(false);
+
+  expect(evicted).toEqual([
+    ['a', 'delete'],
+    ['b', 'expired'],
+  ]);
+  expect(cache.size).toBe(0);
+});
+
+test('lru size and keys leave expired entries untouched', () => {
+  let t = 0;
+  const evicted: string[] = [];
+  const cache = new LRU<string, number>(3, 100, () => t);
+  cache.onEvict = (key) => evicted.push(key);
+
+  cache.set('a', 1);
+  t = 60;
+  cache.set('b', 2);
+  t = 100;
+
+  expect(cache.size).toBe(1);
+  expect(cache.keys()).toEqual(['b']);
+  expect(evicted).toEqual([]);
+});
